To achieve this task using JavaScript, you can create a function that iterates through each property of an object (or an array) represented as a dot-separated string. The function will then check if any of these properties match the specified key. Here's how you could implement such a function:

```javascript
function getMatchingEntries(obj, keyString) {
    const parts = keyString.split('.');
    let currentObj = obj;

    for (let part of parts) {
        // Check if the current part is an object or array
        if (currentObj && typeof currentObj === 'object' && !Array.isArray(currentObj)) {
            // Get the next level of the tree
            currentObj = currentObj[part];
        } else if (Array.isArray(currentObj)) {
            // Check if we have reached an array with no further keys
            if (!currentObj.includes(part)) {
                break;
            }
            currentObj = currentObj.find(item => item === part);
        } else {
            // If not an object or array, return early
            return null;
        }
    }

    return currentObj;
}

