To retrieve and organize the upcoming races for each rider from the ProcyclingStats API, you'll need to follow these steps:

1. Fetch all riders' data.
2. For each rider, fetch their upcoming race participation information.

Here's how you could implement this in Python:

```python
import requests

# Define your API key (you should replace 'your_api_key' with your actual ProcyclingStats API key)
api_key = 'your_api_key'

def get_riders():
    url = f'https://www.procyclingstats.com/api/v1/athletes?apikey={api_key}'
    response = requests.get(url)
    if response.status_code == 200:
        return response.json()
    else:
        print(f"Failed to fetch riders: {response.status_code}")
        return []

def get_upcoming_participations(rider_id):
    url = f'https://www.procyclingstats.com/api/v1/participation/upcoming/{rider_id}?apikey={api_key}'
    response = requests.get(url)
    if response.status_code == 200:
        return response.json()
    else:
        print(f"Failed to fetch upcoming participations for rider {rider_id}: {response.status_code}")
        return []

